/* Exact binary support filtering, declared examples, and separate global/board models. */
(()=>{'use strict';
const models=new Map(JSON.parse(document.querySelector('#csp-model-data').textContent).models.map(m=>[m.id,m]));
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const mathText=s=>esc(s).replace(/\b[A-Z]=(?:[A-Z]|[0-9])\b|[0-9]+\s*[→≤≥≠]\s*[0-9]+/g,m=>'<span class="csp-math">'+m+'</span>');
const clone=x=>JSON.parse(JSON.stringify(x));const fmt=a=>'{'+a.join(', ')+'}';let uid=0;
function graph(m,f,mark){
 const n=m.variables.length,W=620,H=n<=2?160:350;
 const pos=new Map(m.variables.map((v,i)=>{const a=-Math.PI/2+2*Math.PI*i/n;return[v,n===1?[310,80]:n===2?[150+320*i,80]:[310+235*Math.cos(a),175+112*Math.sin(a)]]}));
 function ports(x,y){const a=pos.get(x),b=pos.get(y),dx=b[0]-a[0],dy=b[1]-a[1];const t=1/Math.max(Math.abs(dx)/62,Math.abs(dy)/34);return[a[0]+dx*t,a[1]+dy*t,b[0]-dx*t,b[1]-dy*t];}
 function path(x,y,cls,arrow){const p=ports(x,y);return`<path class="${cls}" data-from="${esc(x)}" data-to="${esc(y)}" d="M${p[0]} ${p[1]} L${p[2]} ${p[3]}"${arrow?` marker-end="url(#${mark})"`:''}/>`;}
 return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(m.title+'; '+f.kind)}"><defs><marker id="${mark}" viewBox="0 0 10 10" refX="10" refY="5" markerWidth="8" markerHeight="8" orient="auto"><path d="M0 0 L10 5 L0 10 Z" fill="#176a78"/></marker></defs>`+m.constraints.map(c=>path(c.x,c.y,'csp-edge',false)).join('')+(f.arc?path(...f.arc,'csp-active',true):'')+m.variables.map(v=>{const [x,y]=pos.get(v),changed=f.before&&JSON.stringify(f.before[v])!==JSON.stringify(f.domains[v]);return`<g class="csp-node${changed?' changed':''}${f.domains[v].length?'':' empty'}" data-variable="${esc(v)}"><rect x="${x-62}" y="${y-34}" width="124" height="68" rx="11"/><text x="${x}" y="${y-8}" text-anchor="middle">${esc(v)}</text><text x="${x}" y="${y+18}" text-anchor="middle">${esc(fmt(f.domains[v]))}</text></g>`}).join('')+'</svg>';
}
class Player{
 constructor(host,provided){this.host=host;this.ids=host.dataset.models?.split(',')||[provided.id];this.model=provided||models.get(this.ids[0]);this.index=0;this.timer=null;this.marker='csp-arrow-'+(++uid);
 host.innerHTML=`<h3>${esc(host.dataset.title||this.model.title)}</h3>`+(this.ids.length>1?`<label>Compare the declared case <select data-case>${this.ids.map(id=>`<option value="${id}">${esc(models.get(id).title)}</option>`).join('')}</select></label>`:'')+`<div class="csp-controls"><button data-first type="button">Restart</button><button data-prev type="button">Previous</button><button data-play type="button" aria-pressed="false">Play</button><button data-next type="button">Next</button><label>Checkpoint <input data-seek type="range" min="0" value="0" aria-label="${esc(this.model.title)} checkpoint"></label><label>Step time <select data-speed><option value="1400">1.4 seconds</option><option value="900" selected>0.9 seconds</option><option value="500">0.5 seconds</option></select></label></div><p class="csp-counter"></p><div class="csp-stage"></div><p class="csp-caption" aria-live="polite"></p><p class="csp-reason"></p><p class="csp-queue"></p><div class="csp-supports"></div><p class="csp-relations"></p><p class="csp-legend"></p><div class="csp-print"></div>`;
 this.seek=host.querySelector('[data-seek]');host.querySelector('[data-first]').onclick=()=>this.go(0);host.querySelector('[data-prev]').onclick=()=>this.go(this.index-1);host.querySelector('[data-next]').onclick=()=>this.go(this.index+1);this.seek.oninput=()=>this.go(+this.seek.value);host.querySelector('[data-play]').onclick=()=>{if(this.timer)this.pause();else{if(this.index===this.model.frames.length-1)this.index=0;host.querySelector('[data-play]').setAttribute('aria-pressed','true');host.querySelector('[data-play]').textContent='Pause';this.timer=setInterval(()=>{this.index=Math.min(this.index+1,this.model.frames.length-1);this.render();if(this.index===this.model.frames.length-1)this.pause()},+host.querySelector('[data-speed]').value);}};host.querySelector('[data-speed]').onchange=()=>this.pause();const s=host.querySelector('[data-case]');if(s)s.onchange=()=>{this.pause();this.model=models.get(s.value);this.index=0;this.render();};this.render();
 }
 pause(){clearInterval(this.timer);this.timer=null;this.host.querySelector('[data-play]').setAttribute('aria-pressed','false');this.host.querySelector('[data-play]').textContent='Play';}
 go(n){this.pause();this.index=Math.max(0,Math.min(n,this.model.frames.length-1));this.render();}
 render(){const h=this.host,m=this.model,f=m.frames[this.index];this.seek.max=m.frames.length-1;this.seek.value=this.index;h.querySelector('[data-prev]').disabled=this.index===0;h.querySelector('[data-next]').disabled=this.index===m.frames.length-1;h.querySelector('.csp-counter').textContent=`Checkpoint ${this.index+1} of ${m.frames.length} · ${f.kind} · ${f.pairChecks} relation checks in this invocation/segment`;
 h.querySelector('.csp-stage').innerHTML=graph(m,f,this.marker);h.querySelector('.csp-caption').textContent=f.arc?`Revise ${f.arc[0]} → ${f.arc[1]}; tail values seek support in the head domain.`:f.kind==='restore'?'Restore the parent before the sibling branch.':f.kind==='failure'?'Failure under the currently displayed assumptions.':f.kind==='fixed-point'?'Queue exhausted: arc consistency established, not general satisfiability.':f.kind==='assumption'?'Introduce the explicitly stated branch assumption.':'Read the declared domains and pending tests.';
 h.querySelector('.csp-reason').innerHTML=mathText(f.why)+(f.removed.length?` Removed tail values: <span class="csp-math">${f.removed.join(', ')}</span>.`:'');h.querySelector('.csp-queue').innerHTML='Pending directed arcs: <span class="csp-math">'+(f.queue.map(a=>a.join(' → ')).join(' ; ')||'none')+'</span>';
 h.querySelector('.csp-supports').innerHTML=f.supports.length?`<table><thead><tr><th>Tail candidate before REVISE</th><th>Head witness</th><th>Decision</th></tr></thead><tbody>${f.supports.map(s=>`<tr><td class="csp-math">${s.tail}</td><td class="csp-math">${s.head===null?'none':s.head}</td><td>${s.head===null?'Delete: no compatible live value':'Keep: witness found'}</td></tr>`).join('')}</tbody></table>`:'<p>No individual support test occurs at this checkpoint.</p>';
 h.querySelector('.csp-relations').innerHTML='Declared binary relations: '+m.constraints.map(c=>`<span class="csp-math">${esc(c.label.replace(/!=/g,'≠').replace(/<=/g,'≤'))}</span>`).join(' ; ');h.querySelector('.csp-legend').innerHTML=mathText((m.legend||'')+' Arrow tip touches the head card; only the tail is revised. Amber means a domain changed at this step. Scroll the compact canvas horizontally on narrow screens.');
 }
 print(){const m=this.model,indices=[0,m.frames.length-1];const fail=m.frames.findIndex(f=>f.kind==='failure');if(fail>=0&&!indices.includes(fail))indices.splice(1,0,fail);this.host.querySelector('.csp-print').innerHTML=indices.map((k,i)=>`<p>Checkpoint ${k+1}: ${esc(m.frames[k].why)}</p><div class="csp-stage">${graph(m,m.frames[k],this.marker+'-print-'+i)}</div>`).join('');}
}
const players=[...document.querySelectorAll('.csp-player')].map(h=>new Player(h));
function validate(raw){
 if(!raw||typeof raw!=='object'||Array.isArray(raw)||!raw.domains||typeof raw.domains!=='object'||Array.isArray(raw.domains)||!Array.isArray(raw.constraints))throw Error('Supply an object with a domains object and a constraints array.');
 const vs=Object.keys(raw.domains);if(vs.length>6)throw Error('Use at most six variables.');for(const v of vs){if(!/^[A-Z][A-Z0-9_]{0,3}$/.test(v))throw Error('Variable names use one to four uppercase letters, digits or underscores, starting with a letter.');const d=raw.domains[v];if(!Array.isArray(d)||d.length>5||d.some(a=>!Number.isInteger(a)||Math.abs(a)>9)||new Set(d).size!==d.length)throw Error('Domains contain at most five distinct integers from -9 through 9; an empty domain is allowed.');}
 if(raw.constraints.length>30)throw Error('Use at most thirty binary table declarations.');
 const rel=new Map(),key=(x,y)=>x+'|'+y,domains=clone(raw.domains);
 for(const c of raw.constraints){if(!c||!vs.includes(c.x)||!vs.includes(c.y)||c.x===c.y||!Array.isArray(c.allowed)||c.allowed.length>25)throw Error('Each constraint needs two distinct declared endpoints and at most 25 allowed pairs.');let pairs=new Set();for(const p of c.allowed){if(!Array.isArray(p)||p.length!==2||!domains[c.x].includes(p[0])||!domains[c.y].includes(p[1]))throw Error('Every allowed pair must belong to the original endpoint domains.');pairs.add(p.join(','));}const old=rel.get(key(c.x,c.y));if(old)pairs=new Set([...pairs].filter(p=>old.has(p)));rel.set(key(c.x,c.y),pairs);rel.set(key(c.y,c.x),new Set([...pairs].map(p=>p.split(',').reverse().join(','))));}
 return{vs,domains,rel,key};
}
function run(raw){const {vs,domains:D,rel,key}=validate(raw),neighbors=new Map(vs.map(x=>[x,vs.filter(y=>rel.has(key(x,y)))])),Q=vs.flatMap(x=>neighbors.get(x).map(y=>[x,y])),frames=[];let checks=0;
 function emit(kind,why,arc=null,removed=[],supports=[],before=null){frames.push({kind,why,arc,domains:clone(D),queue:clone(Q),removed,supports,before,pairChecks:checks});}
 emit('initial','Laboratory input has explicit binary tables. Unary restrictions must already be reflected in domains.');let failed=vs.some(v=>!D[v].length);if(failed)emit('failure','An initially empty domain makes the input impossible, including isolated variables.');
 while(Q.length&&!failed){const[x,y]=Q.shift(),before=clone(D),removed=[],supports=[];for(const a of [...D[x]]){let witness=null;for(const b of D[y]){checks++;if(rel.get(key(x,y)).has([a,b].join(','))){witness=b;break;}}supports.push({tail:a,head:witness});if(witness===null){D[x]=D[x].filter(v=>v!==a);removed.push(a);}}emit('revise','Delete a tail candidate exactly when no current head witness exists.',[x,y],removed,supports,before);if(removed.length){if(!D[x].length){failed=true;emit('failure','No solution extends these input domains; a domain has become empty.',[x,y]);break;}for(const z of neighbors.get(x))if(z!==y&&!Q.some(([a,b])=>a===z&&b===x))Q.push([z,x]);emit('requeue','Only existing incoming arcs may have lost a support.',[x,y]);}}
 if(!failed)emit('fixed-point','This is a local support fixed point. It does not prove that a joint solution exists.');
 return{id:'lab',title:'Your declared finite binary CSP',variables:vs,domains:clone(raw.domains),constraints:vs.flatMap((x,i)=>vs.slice(i+1).filter(y=>rel.has(key(x,y))).map(y=>({x,y,allowed:[...rel.get(key(x,y))].map(p=>p.split(',').map(Number)),label:x+' ~ '+y}))),frames,failed};
}
const lab=document.querySelector('.csp-lab');let labPlayer;
if(lab){const input=lab.querySelector('textarea'),preset=lab.querySelector('[data-preset]');for(const id of ['strict-3','cycle-3','chain-mac','auth-numeric']){const option=document.createElement('option');option.value=id;option.textContent=models.get(id).title;preset.append(option);}function fill(){const m=models.get(preset.value);input.value=JSON.stringify({domains:m.domains,constraints:m.constraints.map(({x,y,allowed})=>({x,y,allowed}))},null,2);}preset.onchange=fill;fill();lab.querySelector('[data-run]').onclick=()=>{lab.querySelector('.csp-error').textContent='';try{const m=run(JSON.parse(input.value));if(labPlayer)labPlayer.pause();const host=lab.querySelector('.csp-lab-result');host.innerHTML='';labPlayer=new Player(host,m);}catch(e){lab.querySelector('.csp-error').textContent='Input not run: '+e.message;}};lab.querySelector('[data-run]').click();}
const specials=[];
for(const h of document.querySelectorAll('[data-special="queens"]')){let rows=[1,1,3,4];const opts=[[1,1,3,4],[2,4,1,3],[3,1,4,2]];h.innerHTML='<h3>Queen attacks use the actual board coordinates</h3><div class="special-controls"><button type="button" data-board>Next declared board</button><label>First queen row <input type="range" min="1" max="4" value="1" aria-label="First queen row"></label></div><div class="special-stage"></div><p class="special-note" aria-live="polite"></p>';let p=0;function draw(){const attacks=[];for(let i=0;i<4;i++)for(let j=i+1;j<4;j++)if(rows[i]===rows[j]||Math.abs(rows[i]-rows[j])===j-i)attacks.push([i,j]);h.querySelector('.special-stage').innerHTML='<svg viewBox="0 0 380 330" role="img" aria-label="Four queen board and attacking pairs">'+Array.from({length:16},(_,k)=>{const x=k%4,y=Math.floor(k/4);return`<rect x="${55+x*60}" y="${35+y*60}" width="60" height="60" fill="${(x+y)%2?'#e3edf0':'#f7f2e7'}"/>`}).join('')+attacks.map(([i,j])=>`<line x1="${85+i*60}" y1="${65+(rows[i]-1)*60}" x2="${85+j*60}" y2="${65+(rows[j]-1)*60}" stroke="#b34e49" stroke-width="3" opacity=".7"/>`).join('')+rows.map((r,i)=>`<circle cx="${85+i*60}" cy="${65+(r-1)*60}" r="17" fill="#1c6172"/><text x="${85+i*60}" y="${71+(r-1)*60}" text-anchor="middle" style="fill:white">Q</text><text class="small" x="${85+i*60}" y="302" text-anchor="middle">Q${i+1}</text>`).join('')+'</svg>';h.querySelector('.special-note').textContent=`Rows by column: (${rows.join(', ')}). Attacking pairs: ${attacks.length}. `+(attacks.length?attacks.map(([i,j])=>`Q${i+1}–Q${j+1}`).join(', '):'Every row and diagonal restriction is satisfied.');h.dataset.conflicts=attacks.length;h.dataset.rows=rows.join(',');}
 h.querySelector('[data-board]').onclick=()=>{p=(p+1)%opts.length;rows=[...opts[p]];h.querySelector('input').value=rows[0];draw();};h.querySelector('input').oninput=e=>{rows[0]=+e.target.value;draw();};draw();specials.push({host:h,draw});}
for(const h of document.querySelectorAll('[data-special="hall"]')){let k=0;h.innerHTML='<h3>One joint all-different allocation</h3><div class="special-controls"><button type="button" data-hall>Next support claim</button></div><div class="special-stage"></div><p class="special-note" aria-live="polite"></p>';const states=[{z:null,links:[],text:'X and Y can use only 1 and 2. Their two-variable Hall set reserves both values; Z needs 3.'},{z:1,links:[['Z',1],['X',2]],text:'Force Z=1. X can use 2, but Y then has no distinct available value. No complete matching can contain Z=1.'},{z:2,links:[['Z',2],['X',1]],text:'Force Z=2. X can use 1, but Y is blocked. The same Hall set rules out Z=2.'},{z:3,links:[['Z',3],['X',1],['Y',2]],text:'Force Z=3. X=1,Y=2 gives a complete matching. Swapping X and Y gives the second solution.'}];function draw(){const s=states[k],left={X:65,Y:155,Z:245},right={1:65,2:155,3:245};h.querySelector('.special-stage').innerHTML='<svg viewBox="0 0 480 310" role="img" aria-label="All-different variable to value matching">'+['X','Y','Z'].flatMap(v=>(v==='Z'?[1,2,3]:[1,2]).map(a=>`<line x1="125" y1="${left[v]}" x2="355" y2="${right[a]}" stroke="${s.links.some(([x,b])=>x===v&&b===a)?'#146e78':'#d2dfe2'}" stroke-width="${s.links.some(([x,b])=>x===v&&b===a)?5:1.5}"/>`)).join('')+['X','Y','Z'].map(v=>`<rect x="55" y="${left[v]-24}" width="70" height="48" rx="8" fill="#ecf4f5" stroke="#8bb1bc"/><text x="90" y="${left[v]+6}" text-anchor="middle">${v}</text>`).join('')+[1,2,3].map(a=>`<circle cx="379" cy="${right[a]}" r="24" fill="#fff7e8" stroke="#bc9c64"/><text x="379" y="${right[a]+6}" text-anchor="middle">${a}</text>`).join('')+'</svg>';h.querySelector('.special-note').textContent=s.text;h.dataset.step=k;}h.querySelector('button').onclick=()=>{k=(k+1)%states.length;draw()};draw();specials.push({host:h,draw});}
let printState;
addEventListener('beforeprint',()=>{if(printState)return;printState=[...document.querySelectorAll('details')].map(d=>[d,d.open]);printState.forEach(([d])=>d.open=true);players.forEach(p=>{p.pause();p.print()});if(labPlayer){labPlayer.pause();labPlayer.print();}});
addEventListener('afterprint',()=>{if(printState){printState.forEach(([d,open])=>d.open=open);printState=null;}});
window.__cspTeaching={models,players,run,validate,graph,specials,get labPlayer(){return labPlayer;}};
})();
